    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    priority_queue<long long> heap(a.begin(), a.end());
    while (heap.size() > 1) {
        long long first = heap.top();
        heap.pop();
        long long second = heap.top();
        heap.pop();
        if (first != second) heap.push(first - second);
